/// C2 lessons 481-510: advanced discourse, translation and strategic governance.
class C2MasteryCourseData {
 static List<String> _rotate(List<String> v,int a)=>List<String>.generate(v.length,(i)=>v[(i-a+v.length)%v.length]);
 static B1Question _q(String p,List<String> o,int a,String e)=>B1Question(p,_rotate(o,a),a,e);
 static B1Lesson _build(_Spec s){final n=s.number;final w=[s.meaning,'التعبير عن المكان','التعبير عن الزمن الماضي','طلب الإذن'];final tr=[s.translation,'لم يبدأ الاجتماع بعد.','سأعود إلى المنزل غداً.','لا تتضمن الجملة هذا المعنى.'];final fm=[s.form,'geçmiş zaman','istek kipi','yer tamlayıcısı'];final fn=[s.functionText,'تحديد المكان فقط','تغيير زمن الجملة فقط','تكوين سؤال عن السعر'];return B1Lesson(unitId:s.unitId,globalNumber:n,title:s.title,goal:s.goal,rule:s.rule,examples:[s.sentence+' | '+s.translation,s.example],dialogue:s.dialogue,speakingTask:s.task,questions:[_q('ما معنى «${s.term}»؟',w,n%4,'«${s.term}» تعني: ${s.meaning}.'),_q('ما ترجمة الجملة التركية؟',tr,(n+1)%4,s.translation),_q('أي تعبير يرتبط بمهارة الدرس؟',fm,(n+2)%4,'التعبير المستهدف «${s.form}». '+s.rule),_q('ما الوظيفة التواصلية الأساسية؟',fn,(n+3)%4,s.functionText),_q('أي ممارسة تثبت إتقان المهارة؟',[s.task,'حفظ كلمات دون سياق','نسخ نص دون فهم','تجاهل القرائن والأدلة'],(n+1)%4,s.task)]);}
 static final List<B1Lesson> lessons=[
_Spec(unitId:'c2-u7',number:481,title:'تحليل الأداء الشفهي عالي التعقيد',goal:'إدارة خطاب شفهي طويل يجمع التحليل والارتجال والتفاعل.',rule:'ابنِ أطروحة شفوية واضحة، ووازن بين التلقائية والدقة، وعدّل المسار وفق أسئلة الجمهور.',term:'ileri sözlü anlatım',meaning:'خطاب شفهي متقدم',sentence:'Karmaşık bir konuyu farklı dinleyici gruplarına göre yeniden yapılandırdım.',translation:'أعدت تنظيم موضوع معقد وفق مجموعات مختلفة من المستمعين.',form:'sözlü söylem stratejisi',functionText:'تنظيم الخطاب الشفهي لجمهور متنوع.',task:'قدم عرضاً متخصصاً ثم أعد شرحه لجمهور غير متخصص.',example:'Sözlü anlatımımı dinleyici tepkilerine göre uyarladım.|كيفت خطابي وفق استجابات المستمعين.',dialogue:'A: Açıklamayı değiştirmek gerekir mi؟ — هل يلزم تغيير الشرح؟\nB: Dinleyicinin sorularına göre derinliği ayarlayalım. — لنضبط العمق وفق أسئلة المستمع.'),
_Spec(unitId:'c2-u7',number:482,title:'التحليل الفوري للمداخلات',goal:'التقاط حجة المتحدث وإعادة بنائها والرد عليها دون إعداد طويل.',rule:'استمع للفكرة والقرينة والافتراض، ثم لخصها بدقة قبل الرد.',term:'anlık çözümleme',meaning:'تحليل فوري',sentence:'Konuşmacının savını anında özetleyip temel varsayımını sorguladım.',translation:'لخصت حجة المتحدث فوراً وتساءلت عن افتراضها الأساسي.',form:'anlık argüman takibi',functionText:'متابعة الحجة والرد عليها فورياً.',task:'شارك في نقاش سريع وسجل الحجة والافتراض والرد في نقاط.',example:'Müdahalenin ana fikrini kaybetmeden yanıt verdim.|أجبت دون فقدان الفكرة الرئيسة للمداخلة.',dialogue:'A: Bu kadar hızlı nasıl yanıt verdin؟ — كيف أجبت بهذه السرعة؟\nB: Önce savı özetleyip sonra varsayımı belirledim. — لخصت الحجة أولاً ثم حددت الافتراض.'),
_Spec(unitId:'c2-u7',number:483,title:'التفسير المتزامن للمفاهيم المتخصصة',goal:'شرح المفهوم المعقد أثناء الاستماع مع الحفاظ على الدقة.',rule:'حدد المفهوم المحوري، واستخدم تعريفاً وظيفياً ومثالاً موجزاً، وتجنب التبسيط المخل.',term:'eşzamanlı açıklama',meaning:'شرح متزامن',sentence:'Karmaşık terimi kısa bir tanım ve örnekle açıkladım.',translation:'شرحت المصطلح المعقد بتعريف قصير ومثال.',form:'anlık kavramsal açıklama',functionText:'شرح المفاهيم أثناء تدفق الحوار.',task:'اشرح خمسة مصطلحات متخصصة فور سماعها مع مثال لكل منها.',example:'Terimi bağlamı bozmadan açıkladım.|شرحت المصطلح دون الإخلال بالسياق.',dialogue:'A: Tanımı şimdi verebilir misin؟ — هل تستطيع تقديم التعريف الآن؟\nB: Evet, önce işlevini sonra örneğini belirteyim. — نعم، سأذكر وظيفته أولاً ثم مثاله.'),
_Spec(unitId:'c2-u7',number:484,title:'إدارة الاختلاف الفكري الحاد',goal:'الحفاظ على نقاش منتج عند تعارض المواقف الأساسية.',rule:'حدد نقطة الخلاف بدقة، واعترف بالجزء المشترك، واطلب معياراً يمكن للطرفين قبوله.',term:'derin görüş ayrılığı',meaning:'اختلاف عميق في الرأي',sentence:'Temel ayrılığı kişiselleştirmeden ortak ölçütler üzerinden tartıştık.',translation:'ناقشنا الخلاف الأساسي وفق معايير مشتركة دون تحويله إلى خلاف شخصي.',form:'yapıcı ihtilaf',functionText:'إدارة الخلاف الفكري بموضوعية.',task:'أدر مناظرة حول قضية خلافية واكتب نقاط الاتفاق والاختلاف.',example:'Görüş ayrılığını analitik bir zeminde tuttum.|أبقيت الاختلاف في إطار تحليلي.',dialogue:'A: Bu konuda uzlaşamayacak mıyız؟ — ألن نتوصل إلى اتفاق؟\nB: Önce hangi ölçütlerde ayrıldığımızı netleştirelim. — لنوضح أولاً المعايير التي نختلف حولها.'),
_Spec(unitId:'c2-u7',number:485,title:'توظيف الصمت والوقفات في الإقناع',goal:'استخدام الوقفات لتأكيد الفكرة وإتاحة وقت للمعالجة.',rule:'ضع الوقفة بعد الفكرة المحورية لا وسط العلاقة النحوية، وراقب أثرها على الجمهور.',term:'retorik duraklama',meaning:'وقفة بلاغية',sentence:'Ana savdan sonra kısa bir duraklama dinleyicinin dikkatini topladı.',translation:'جمعت وقفة قصيرة بعد الحجة الرئيسة انتباه المستمع.',form:'sözlü vurgu',functionText:'تعزيز المعنى عبر الوقف والإيقاع.',task:'سجل خطاباً وقارن أثر نسختين تختلفان في الوقفات.',example:'Duraklamaları anlamın yapısına göre kullandım.|استخدمت الوقفات وفق بنية المعنى.',dialogue:'A: Neden cümleden sonra bekledin؟ — لماذا انتظرت بعد الجملة؟\nB: Ana fikrin dinleyicide yerleşmesini istedim. — أردت أن تستقر الفكرة الرئيسة لدى المستمع.'),
_Spec(unitId:'c2-u7',number:486,title:'الرد على الأسئلة المركبة والمتعددة',goal:'تفكيك سؤال يضم عدة مطالب والإجابة عنها بترتيب.',rule:'أعد صياغة محاور السؤال، وأجب عن كل محور، وصرح بما يحتاج إلى بيانات إضافية.',term:'çok katmanlı soru',meaning:'سؤال متعدد الطبقات',sentence:'Sorunun üç boyutunu ayrı ayrı ele alıp sonunda birleştirdim.',translation:'تناولت أبعاد السؤال الثلاثة منفصلة ثم جمعتها في النهاية.',form:'yapılandırılmış yanıt',functionText:'تنظيم الإجابة عن سؤال متعدد الأجزاء.',task:'تدرب على أسئلة تضم ثلاثة أجزاء وقدم إجابة متوازنة.',example:'Sorunun tüm bileşenlerine sırayla yanıt verdim.|أجبت عن جميع مكونات السؤال بالتتابع.',dialogue:'A: İlk olarak hangi kısmı yanıtlayalım؟ — أي جزء نجيب عنه أولاً؟\nB: Önce kavramı, sonra kanıtı ve sonucu. — المفهوم أولاً ثم الدليل والنتيجة.'),
_Spec(unitId:'c2-u7',number:487,title:'المناظرة القائمة على النماذج التفسيرية',goal:'مقارنة نماذج تفسيرية متعددة والدفاع عن حدود كل نموذج.',rule:'حدد تنبؤات النموذج وشروطه وما يفسره وما يتركه خارج نطاقه.',term:'açıklama modeli',meaning:'نموذج تفسيري',sentence:'İki modelin açıklama kapsamını ve varsayımlarını karşılaştırdım.',translation:'قارنت نطاق التفسير والافتراضات في نموذجين.',form:'model karşılaştırması',functionText:'تقييم النماذج من حيث القوة والحدود.',task:'دافع عن نموذجين تفسيريين في مناظرة قصيرة.',example:'Modelleri aynı ölçütlerle değerlendirdim.|قيّمت النماذج بالمعايير نفسها.',dialogue:'A: Tek bir model yeterli mi؟ — هل يكفي نموذج واحد؟\nB: Olguyu açıklamak için birden fazla yaklaşım gerekebilir. — قد نحتاج إلى أكثر من مقاربة لتفسير الظاهرة.'),
_Spec(unitId:'c2-u7',number:488,title:'إدارة الحوار متعدد اللغات',goal:'تسهيل حوار يستخدم المشاركون فيه لغات وخلفيات مختلفة.',rule:'تحقق من المصطلحات المشتركة، واطلب إعادة الصياغة عند الحاجة، ووثق المعاني المتفق عليها.',term:'çok dilli iletişim',meaning:'تواصل متعدد اللغات',sentence:'Terimlerin farklı dillerdeki karşılıklarını görüşme boyunca tutarlı kullandık.',translation:'استخدمنا المقابلات اللغوية للمصطلحات بصورة متسقة طوال الاجتماع.',form:'diller arası arabuluculuk',functionText:'ضمان وضوح المعنى بين لغات متعددة.',task:'أدر جلسة متعددة اللغات مع مسرد مشترك للمصطلحات.',example:'Anlam kaymasını önlemek için terimleri doğruladım.|تحققت من المصطلحات لمنع انزياح المعنى.',dialogue:'A: Bu terimi aynı anlamda mı kullanıyoruz؟ — هل نستخدم هذا المصطلح بالمعنى نفسه؟\nB: Ortak tanımı kontrol edelim. — لنراجع التعريف المشترك.'),
_Spec(unitId:'c2-u7',number:489,title:'تقييم أثر الخطاب الشفهي',goal:'تحليل كيف أثرت بنية الحديث ونبرته والأدلة في استجابة الجمهور.',rule:'قارن هدف المتحدث بالاستجابة الفعلية، وميز الإقناع من مجرد الموافقة اللحظية.',term:'sözlü etki',meaning:'أثر شفهي',sentence:'Dinleyici tepkileri, örneklerin soyut açıklamalardan daha etkili olduğunu gösterdi.',translation:'أظهرت استجابات المستمعين أن الأمثلة أكثر تأثيراً من الشروح المجردة.',form:'etki analizi',functionText:'تقييم أثر العرض الشفهي.',task:'حلل تسجيل عرض واستجابات الجمهور وحدد ثلاثة تحسينات.',example:'Sunumun etkisini gözlemlenebilir tepkilerle değerlendirdim.|قيّمت أثر العرض من خلال الاستجابات الملحوظة.',dialogue:'A: Alkış başarıyı kanıtlar mı؟ — هل يثبت التصفيق النجاح؟\nB: Tek başına değil; anlama ve geri bildirim de önemli. — ليس وحده؛ فالفهم والتغذية الراجعة مهمان أيضاً.'),
_Spec(unitId:'c2-u7',number:490,title:'مشروع الخطاب الشفهي المتقدم',goal:'إنتاج عرض ومناظرة وإجابة فورية ضمن مشروع واحد.',rule:'اجمع الأدلة، وحدد الجمهور، وقدم الأطروحة، ثم تعامل مع اعتراضات وأسئلة غير متوقعة.',term:'ileri sözlü proje',meaning:'مشروع شفهي متقدم',sentence:'Araştırma bulgularını sunup ardından eleştirel soruları yanıtladım.',translation:'عرضت نتائج البحث ثم أجبت عن أسئلة نقدية.',form:'bütünleşik sözlü performans',functionText:'دمج العرض والمناظرة والرد الفوري.',task:'نفذ مشروعاً شفهياً من عرض ومناظرة وجلسة أسئلة.',example:'Sözlü performansımı kanıt ve etkileşimle tamamladım.|أكملت أدائي الشفهي بالأدلة والتفاعل.',dialogue:'A: En zor bölüm hangisiydi؟ — ما أصعب جزء؟\nB: Beklenmedik sorulara tutarlı yanıt vermek. — الإجابة المتماسكة عن الأسئلة غير المتوقعة.'),
_Spec(unitId:'c2-u8',number:491,title:'الترجمة المتخصصة للمفاهيم النظرية',goal:'نقل المصطلحات النظرية مع الحفاظ على دقتها وحدودها.',rule:'قارن تعريفات المصطلح في التخصصين، وحدد المقابل مع شرح عند غياب التطابق.',term:'kuramsal terim',meaning:'مصطلح نظري',sentence:'Kavramın disiplinler arasındaki anlam farkını çeviride belirttim.',translation:'أوضحت في الترجمة اختلاف معنى المفهوم بين التخصصات.',form:'uzmanlık çevirisi',functionText:'ترجمة المفاهيم النظرية بدقة.',task:'أنشئ مسرداً ثنائياً لعشرين مصطلحاً نظرياً مع تعريفات.',example:'Terimlerin kuramsal kapsamını karşılaştırdım.|قارنت النطاق النظري للمصطلحات.',dialogue:'A: Tek bir karşılık kullanabilir miyiz؟ — هل يمكننا استخدام مقابل واحد؟\nB: Alanın tanımına göre değişebilir. — قد يختلف بحسب تعريف المجال.'),
_Spec(unitId:'c2-u8',number:492,title:'تحرير الترجمة الأدبية متعددة الطبقات',goal:'الحفاظ على الصوت والصورة والإيحاء في نص أدبي معقد.',rule:'راجع المعنى الحرفي والصورة والنبرة والإيقاع، وحدد ما يحتاج إلى تعويض أسلوبي.',term:'çok katmanlı çeviri',meaning:'ترجمة متعددة الطبقات',sentence:'Çeviride anlatıcının mesafesini ve ironik tonunu korumaya çalıştım.',translation:'حاولت الحفاظ في الترجمة على مسافة الراوي ونبرته الساخرة.',form:'edebî aktarım',functionText:'نقل طبقات المعنى والأسلوب الأدبي.',task:'حرر ترجمة مقطع أدبي مع شرح ثلاثة قرارات أسلوبية.',example:'Metnin sesini ve imgesel yapısını korudum.|حافظت على صوت النص وبنيته التصويرية.',dialogue:'A: İroniyi doğrudan çevirebilir miyiz؟ — هل يمكن ترجمة السخرية مباشرة؟\nB: Bağlama göre yeniden kurmak gerekebilir. — قد نحتاج إلى إعادة بنائها وفق السياق.'),
_Spec(unitId:'c2-u8',number:493,title:'التوطين اللغوي والثقافي المتقدم',goal:'تكييف المحتوى لجمهور جديد دون فقد الوظيفة أو الهوية.',rule:'حدد العناصر الثابتة والقابلة للتكييف، واختبر الصياغة مع مستخدمين من الجمهور المستهدف.',term:'yerelleştirme',meaning:'توطين لغوي وثقافي',sentence:'Arayüz metinlerini hedef kültürün kullanım alışkanlıklarına göre uyarladık.',translation:'كيفنا نصوص الواجهة وفق عادات الاستخدام في الثقافة المستهدفة.',form:'kültürel yerelleştirme',functionText:'تكييف المحتوى للسياق المحلي.',task:'صمم خطة توطين لمحتوى رقمي تشمل المصطلحات والنبرة والأمثلة.',example:'Yerelleştirme kararlarını kullanıcı beklentileriyle doğruladım.|تحققت من قرارات التوطين وفق توقعات المستخدمين.',dialogue:'A: Her örneği doğrudan çevirelim mi؟ — هل نترجم كل مثال مباشرة؟\nB: İşlevi koruyarak uygun örnek seçelim. — لنختر مثالاً مناسباً مع الحفاظ على الوظيفة.'),
_Spec(unitId:'c2-u8',number:494,title:'إدارة الغموض في الترجمة',goal:'التعامل مع لفظ أو تركيب يحتمل أكثر من معنى في الأصل.',rule:'اجمع القرائن النحوية والسياقية والنصية، ثم اختر حلاً أو أبق الغموض إذا كان مقصوداً.',term:'anlam belirsizliği',meaning:'غموض دلالي',sentence:'Kaynak metindeki belirsizliği çeviride gereksiz yere ortadan kaldırmadım.',translation:'لم أزل في الترجمة الغموض الموجود في النص الأصلي دون داعٍ.',form:'belirsizliği korumak',functionText:'الحفاظ على الغموض المقصود أو حله بدليل.',task:'قارن ترجمتين لعبارة ملتبسة ووضح القرار الأنسب.',example:'Belirsizliğin işlevini metin içinde değerlendirdim.|قيّمت وظيفة الغموض ضمن النص.',dialogue:'A: Belirsizliği mutlaka çözmeli miyiz؟ — هل يجب أن نزيل الغموض دائماً؟\nB: Yazarın amacı buysa korumak daha doğru olabilir. — إذا كان هذا قصد الكاتب فقد يكون الحفاظ عليه أصح.'),
_Spec(unitId:'c2-u8',number:495,title:'المراجعة المقارنة بين الترجمات',goal:'تقييم بدائل ترجمة متعددة وفق معايير واضحة.',rule:'ضع معايير للدقة والطبيعية والنبرة والاتساق، ثم قارن الأثر لا الكلمات منفردة.',term:'çeviri karşılaştırması',meaning:'مقارنة الترجمات',sentence:'Üç çeviri seçeneğini anlam, akıcılık ve üslup açısından değerlendirdim.',translation:'قيّمت ثلاثة خيارات ترجمة من حيث المعنى والسلاسة والأسلوب.',form:'çeviri ölçütleri',functionText:'مقارنة الترجمات وفق معايير متعددة.',task:'قارن ثلاث ترجمات لفقرة واحدة واكتب تبريراً لاختيارك.',example:'Tercihimi açık ölçütlerle gerekçelendirdim.|بررت اختياري بمعايير واضحة.',dialogue:'A: En kısa çeviri en iyi mi؟ — هل أقصر ترجمة هي الأفضل؟\nB: Hayır, doğruluk ve üslup da değerlendirilir. — لا، فالدقة والأسلوب يُقيّمان أيضاً.'),
_Spec(unitId:'c2-u8',number:496,title:'التحرير الأسلوبي للنصوص متعددة المؤلفين',goal:'توحيد صوت النص مع الحفاظ على مساهمات مؤلفين مختلفين.',rule:'حدد مستوى النبرة والمصطلحات، ثم راجع الانتقالات والتكرار والإحالات بين الأقسام.',term:'çok yazarlı metin',meaning:'نص متعدد المؤلفين',sentence:'Farklı yazarların bölümlerini ortak bir üslup çerçevesinde birleştirdim.',translation:'جمعت أقسام كتّاب مختلفين ضمن إطار أسلوبي مشترك.',form:'üslup bütünlüğü',functionText:'تحقيق وحدة أسلوبية في نص متعدد المؤلفين.',task:'حرر تقريراً مشتركاً من أربعة أقسام ووحد نبرته ومصطلحاته.',example:'Metnin sesini tekdüzeleştirmeden tutarlılık sağladım.|حققت الاتساق دون جعل صوت النص رتيباً.',dialogue:'A: Her bölüm aynı tonda mı olmalı؟ — هل يجب أن يكون كل قسم بالنبرة نفسها؟\nB: Genel tutarlılık korunmalı, işlevsel farklılıklar kalabilir. — ينبغي الحفاظ على الاتساق العام مع إبقاء الفروق الوظيفية.'),
_Spec(unitId:'c2-u8',number:497,title:'تقييم الجودة الترجمية',goal:'بناء معيار جودة يقيس الدقة والوظيفة والسياق والأثر.',rule:'حدد الأخطاء الحرجة والثانوية، وقيّم أثرها في الفهم، ولا تساو بين جميع الاختلافات.',term:'çeviri kalite değerlendirmesi',meaning:'تقييم جودة الترجمة',sentence:'Hata türlerini etkilerine göre sınıflandırıp kalite raporu hazırladım.',translation:'صنفت أنواع الأخطاء وفق أثرها وأعددت تقرير جودة.',form:'kalite ölçütleri',functionText:'قياس جودة الترجمة وفق أثر الخطأ.',task:'قيّم ترجمة وفق عشرة معايير وصنف الأخطاء حسب شدتها.',example:'Kalite raporunu somut örneklerle destekledim.|دعمت تقرير الجودة بأمثلة ملموسة.',dialogue:'A: Her küçük fark hata mı؟ — هل كل اختلاف صغير خطأ؟\nB: İşlevi ve anlamı etkileyip etkilemediğine bakmalıyız. — ينبغي النظر فيما إذا كان يؤثر في الوظيفة والمعنى.'),
_Spec(unitId:'c2-u8',number:498,title:'الترجمة في السياق المؤسسي والقانوني',goal:'الحفاظ على الدقة والاتساق والمسؤولية في الوثائق الرسمية.',rule:'ثبت التعريفات، وراجع المصطلحات القانونية، وميز الترجمة من التفسير.',term:'resmî belge çevirisi',meaning:'ترجمة وثيقة رسمية',sentence:'Belgedeki yükümlülükleri ve istisnaları anlam kaybı olmadan aktardım.',translation:'نقلت الالتزامات والاستثناءات في الوثيقة دون فقدان المعنى.',form:'hukuki terminoloji',functionText:'ترجمة الوثائق الرسمية بمصطلحات دقيقة.',task:'ترجم مقطعاً مؤسسياً مع مسرد وملاحظات عن المصطلحات الحساسة.',example:'Resmî terminolojiyi tutarlı biçimde kullandım.|استخدمت المصطلحات الرسمية باتساق.',dialogue:'A: Bu terimi sadeleştirebilir miyiz؟ — هل يمكن تبسيط هذا المصطلح؟\nB: Hukuki kapsamını değiştirmeden açıklayabiliriz. — يمكن شرحه دون تغيير نطاقه القانوني.'),
_Spec(unitId:'c2-u8',number:499,title:'مشروع الترجمة المتخصصة والنشر',goal:'إنتاج نص مترجم محرر وجاهز للنشر مع توثيق قراراته.',rule:'اجمع المسرد والتحرير والمراجعة والتنسيق ومذكرة القرارات في حزمة واحدة.',term:'uzman çeviri projesi',meaning:'مشروع ترجمة متخصص',sentence:'Çeviriyi editörlük ve terim denetiminden geçirerek yayına hazırladık.',translation:'جهزنا الترجمة للنشر بعد التحرير ومراجعة المصطلحات.',form:'yayına hazır çeviri',functionText:'تقديم ترجمة متخصصة جاهزة للنشر.',task:'أنجز ترجمة طويلة مع مسرد ومذكرة تحرير وتقرير جودة.',example:'Çeviri projesini kalite raporuyla tamamladım.|أكملت مشروع الترجمة بتقرير جودة.',dialogue:'A: Son aşamada neyi kontrol ettin؟ — ما الذي راجعته في المرحلة الأخيرة؟\nB: Terimler, kaynak sadakati ve hedef metnin akıcılığı. — المصطلحات وأمانة الأصل وسلاسة النص الهدف.'),
 _Spec(unitId:'c2-u8',number:500,title:'مراجعة الترجمة والتحرير المتقدم',goal:'دمج الترجمة المفاهيمية والأدبية والتوطين والتحرير وضبط الجودة.',rule:'راجع المعنى والنبرة والمصطلح والسياق واتساق النص، ثم وثق القرارات التحريرية.',term:'editoryal son kontrol',meaning:'مراجعة تحريرية نهائية',sentence:'Çeviri ve editörlük kararlarını son kez bütünlük açısından kontrol ettim.',translation:'راجعت قرارات الترجمة والتحرير للمرة الأخيرة من حيث الاتساق.',form:'çeviri ve editörlük denetimi',functionText:'ضمان دقة الترجمة واتساق التحرير قبل التسليم.',task:'راجع نصاً مترجماً نهائياً باستخدام قائمة تحقق تشمل المعنى والأسلوب والمصطلحات والسياق.',example:'Son kontrolde terim birliğini ve anlatım tonunu doğruladım.|تحققت في المراجعة الأخيرة من توحيد المصطلحات ونبرة التعبير.',dialogue:'A: Son teslimden önce neyi kontrol edelim؟ — ماذا نراجع قبل التسليم النهائي؟\\nB: Anlamı, tonu, terimleri ve bütünlüğü. — المعنى والنبرة والمصطلحات والاتساق.'),
_Spec(unitId:'c2-u9',number:501,title:'بناء استراتيجية تفاوض طويلة المدى',goal:'تصميم تفاوض متعدد المراحل مع أهداف ومراجعات متتابعة.',rule:'حدد النتائج المرحلية والبدائل ونقاط إعادة التفاوض وآلية فض الخلاف.',term:'uzun vadeli müzakere',meaning:'تفاوض طويل المدى',sentence:'Aşamalı hedefler belirleyerek uzun vadeli anlaşmanın çerçevesini kurduk.',translation:'وضعنا إطار الاتفاق طويل المدى عبر تحديد أهداف مرحلية.',form:'müzakere stratejisi',functionText:'تخطيط تفاوض متعدد المراحل.',task:'صمم استراتيجية تفاوض من ثلاث مراحل مع بدائل ومؤشرات نجاح.',example:'Müzakere hedeflerini aşamalara ayırdım.|قسمت أهداف التفاوض إلى مراحل.',dialogue:'A: Her aşamada anlaşma kesin mi؟ — هل الاتفاق مؤكد في كل مرحلة؟\nB: Sonuçlar ara değerlendirmelere bağlı olacak. — ستعتمد النتائج على التقييمات المرحلية.'),
_Spec(unitId:'c2-u9',number:502,title:'إدارة المخاطر في الاتفاقات',goal:'تحديد المخاطر التعاقدية والتشغيلية وتوزيع مسؤوليتها.',rule:'حدد احتمال الخطر وأثره وإجراء التخفيف والمسؤول عن المتابعة.',term:'risk paylaşımı',meaning:'تقاسم المخاطر',sentence:'Risklerin hangi tarafça yönetileceğini sözleşmede açıkça belirledik.',translation:'حددنا بوضوح في العقد الطرف المسؤول عن إدارة المخاطر.',form:'risk yönetimi',functionText:'توزيع مسؤوليات المخاطر ومتابعتها.',task:'أعد جدول مخاطر لاتفاق بين مؤسستين مع خطة تخفيف.',example:'Riskleri olasılık ve etki bakımından sınıflandırdım.|صنفت المخاطر بحسب الاحتمال والأثر.',dialogue:'A: Tüm riski tek taraf mı üstlenmeli؟ — هل يتحمل طرف واحد كل المخاطر؟\nB: Kontrol gücüne göre dengeli paylaşım yapılmalı. — ينبغي توزيعها بتوازن وفق القدرة على التحكم.'),
_Spec(unitId:'c2-u9',number:503,title:'صياغة مذكرات القرار الاستراتيجي',goal:'تحويل معلومات متعددة إلى مذكرة تدعم اختياراً محدداً.',rule:'حدد القرار والسياق والخيارات ومعايير المفاضلة والتوصية والمخاطر المتبقية.',term:'karar notu',meaning:'مذكرة قرار',sentence:'Karar notunda seçenekleri aynı ölçütlerle karşılaştırdım.',translation:'قارنت الخيارات في مذكرة القرار وفق المعايير نفسها.',form:'stratejik karar notu',functionText:'إعداد مذكرة قرار موجزة ومدعومة.',task:'اكتب مذكرة قرار من صفحتين تتضمن ثلاثة خيارات وتوصية.',example:'Karar notunu açık ve karşılaştırılabilir verilerle hazırladım.|أعددت مذكرة القرار ببيانات واضحة قابلة للمقارنة.',dialogue:'A: Hangi seçenek daha düşük riskli؟ — أي خيار أقل خطراً؟\nB: Ölçütleri karşılaştırınca ikinci seçenek öne çıkıyor. — عند مقارنة المعايير يبرز الخيار الثاني.'),
_Spec(unitId:'c2-u9',number:504,title:'التواصل مع الجهات التنظيمية',goal:'صياغة تواصل رسمي دقيق مع جهة رقابية أو تنظيمية.',rule:'استخدم لغة موثقة، وأجب عن كل طلب، وحدد الوقائع والوثائق والمسؤوليات.',term:'düzenleyici kurum',meaning:'جهة تنظيمية',sentence:'Talep edilen belgeleri açıklayıcı bir yazıyla birlikte kuruma ilettik.',translation:'أرسلنا الوثائق المطلوبة إلى الجهة مع خطاب توضيحي.',form:'resmî düzenleyici iletişim',functionText:'إدارة المراسلات التنظيمية بدقة.',task:'اكتب رداً رسمياً على طلب معلومات من جهة تنظيمية.',example:'Yanıtı belge ve tarih referanslarıyla yapılandırdım.|نظمت الرد بمراجع الوثائق والتواريخ.',dialogue:'A: Genel bir açıklama yeterli mi؟ — هل يكفي توضيح عام؟\nB: Her talebe belgeye dayalı yanıt vermeliyiz. — يجب أن نجيب عن كل طلب استناداً إلى وثيقة.'),
_Spec(unitId:'c2-u9',number:505,title:'إدارة السمعة والثقة المؤسسية',goal:'التواصل المتسق عند وجود معلومات متضاربة أو انتقادات عامة.',rule:'اعترف بالمعلومة الصحيحة، وصحح الخطأ، وقدم إجراء متابعة قابل للتحقق.',term:'kurumsal itibar',meaning:'سمعة مؤسسية',sentence:'Güveni yeniden kurmak için açık bilgi ve tutarlı uygulama gerekiyor.',translation:'تتطلب استعادة الثقة معلومات واضحة وتطبيقاً متسقاً.',form:'güven yönetimi',functionText:'حماية الثقة عبر الشفافية والاتساق.',task:'صمم خطة استعادة ثقة تشمل رسائل ومؤشرات ومواعيد.',example:'Güvenin sözle değil uygulamayla desteklenmesi gerektiğini vurguladım.|أكدت أن الثقة يجب أن تدعمها الممارسة لا الأقوال.',dialogue:'A: Bir açıklama yeterli olur mu؟ — هل يكفي بيان واحد؟\nB: Sürekli ve ölçülebilir adımlar gerekir. — نحتاج خطوات مستمرة وقابلة للقياس.'),
_Spec(unitId:'c2-u9',number:506,title:'التخطيط لسيناريوهات الأزمات',goal:'إعداد سيناريوهات واستجابات بديلة قبل وقوع الأزمة.',rule:'حدد إشارات الإنذار والسيناريوهات والرسائل والمسؤوليات وآلية التحديث.',term:'senaryo planlaması',meaning:'تخطيط السيناريوهات',sentence:'Olası senaryolar için önceden sorumluluk ve iletişim adımları belirledik.',translation:'حددنا مسبقاً المسؤوليات وخطوات التواصل للسيناريوهات المحتملة.',form:'kriz senaryosu',functionText:'الاستعداد لسيناريوهات مختلفة.',task:'أنشئ ثلاث خطط استجابة لأزمة محتملة مع مؤشرات انتقال.',example:'Her senaryo için uygulanabilir bir yanıt planı hazırladım.|أعددت خطة استجابة قابلة للتنفيذ لكل سيناريو.',dialogue:'A: En kötü senaryoya mı odaklanalım؟ — هل نركز على أسوأ سيناريو؟\nB: Birkaç olasılığı dengeli biçimde değerlendirelim. — لنقيّم عدة احتمالات بصورة متوازنة.'),
_Spec(unitId:'c2-u9',number:507,title:'تقييم أثر السياسات والقرارات',goal:'قياس النتائج المقصودة وغير المقصودة لقرار مؤسسي.',rule:'حدد خط أساس ومؤشرات ومجموعة مقارنة، وافصل الارتباط عن أثر التدخل.',term:'politika etki değerlendirmesi',meaning:'تقييم أثر السياسة',sentence:'Uygulamanın beklenen ve beklenmeyen sonuçlarını ayrı ölçtük.',translation:'قسنا النتائج المتوقعة وغير المتوقعة للتنفيذ بصورة منفصلة.',form:'etki ölçümü',functionText:'تقييم نتائج السياسة وفق مؤشرات.',task:'اكتب إطار تقييم لقرار يتضمن خط أساس وأربعة مؤشرات.',example:'Politikanın etkisini yalnızca tek göstergeye bağlamadım.|لم أربط أثر السياسة بمؤشر واحد فقط.',dialogue:'A: Başarı yalnızca maliyetle mi ölçülür؟ — هل يقاس النجاح بالتكلفة فقط؟\nB: Toplumsal ve uzun vadeli etkiler de incelenmeli. — ينبغي دراسة الآثار الاجتماعية وطويلة المدى أيضاً.'),
_Spec(unitId:'c2-u9',number:508,title:'قيادة التغيير المؤسسي',goal:'توجيه انتقال مؤسسي مع إدارة المقاومة والتواصل والتعلم.',rule:'وضح سبب التغيير ومراحله، واستمع للمخاوف، وحدد الدعم ومؤشرات التبني.',term:'kurumsal dönüşüm',meaning:'تحول مؤسسي',sentence:'Değişim sürecinde çalışanların kaygılarını dinleyip destek mekanizmaları kurduk.',translation:'استمعنا إلى مخاوف الموظفين وأنشأنا آليات دعم خلال التغيير.',form:'değişim yönetimi',functionText:'إدارة التغيير بصورة تشاركية.',task:'ضع خطة تغيير تشمل مراحل ومخاطر وتواصل وتقييم.',example:'Değişimi yalnızca duyurmakla kalmayıp uygulamayı da izledim.|لم أكتف بإعلان التغيير بل تابعت تطبيقه أيضاً.',dialogue:'A: Dirençle nasıl başa çıkacağız؟ — كيف سنتعامل مع المقاومة؟\nB: Kaygıları anlayıp sürece katılım sağlayarak. — بفهم المخاوف وإشراكهم في العملية.'),
_Spec(unitId:'c2-u9',number:509,title:'تقديم تقرير استراتيجي شامل',goal:'عرض تحليل ومخاطر وخيارات وتوصية وقياس أثر في تقرير واحد.',rule:'اجعل الملخص التنفيذي متسقاً مع التفاصيل، واربط كل توصية بدليل ومؤشر متابعة.',term:'stratejik rapor',meaning:'تقرير استراتيجي',sentence:'Rapor, bulguları seçenekler ve uygulanabilir önerilerle birleştiriyor.',translation:'يجمع التقرير النتائج بالخيارات والتوصيات القابلة للتنفيذ.',form:'bütünleşik raporlama',functionText:'إنتاج تقرير يدعم القرارات الاستراتيجية.',task:'أعد تقريراً من خمس صفحات مع ملخص تنفيذي وخطة تنفيذ.',example:'Raporun her önerisini kanıt ve sorumluyla ilişkilendirdim.|ربطت كل توصية في التقرير بدليل ومسؤول.',dialogue:'A: Rapor yalnızca analiz mi sunuyor؟ — هل يقدم التقرير تحليلاً فقط؟\nB: Hayır, uygulama ve izleme planı da içeriyor. — لا، يتضمن أيضاً خطة التنفيذ والمتابعة.'),
_Spec(unitId:'c2-u9',number:510,title:'مشروع القيادة والتواصل المتكامل',goal:'دمج التفاوض والاتفاقات والتواصل المؤسسي وإدارة الأزمات.',rule:'حدد أصحاب المصلحة، وصغ الاتفاق، وأدر الرسائل، ثم قيّم الأثر والنتائج.',term:'stratejik liderlik projesi',meaning:'مشروع قيادة استراتيجية',sentence:'Proje boyunca müzakere, kriz iletişimi ve etki değerlendirmesini birleştirdik.',translation:'جمعنا طوال المشروع بين التفاوض والتواصل في الأزمات وتقييم الأثر.',form:'bütünleşik liderlik',functionText:'إدارة مشروع استراتيجي متعدد الأبعاد.',task:'نفذ محاكاة مؤسسية كاملة مع تقرير ختامي وتقييم ذاتي.',example:'Liderlik kararlarını ölçülebilir sonuçlarla değerlendirdim.|قيّمت قرارات القيادة بنتائج قابلة للقياس.',dialogue:'A: Projenin başarısını ne belirliyor؟ — ما الذي يحدد نجاح المشروع؟\nB: Tutarlı kararlar, açık iletişim ve izlenebilir sonuçlar. — قرارات متسقة وتواصل واضح ونتائج قابلة للمتابعة.'),
 ].map(_build).toList(growable:false);
}
